// One work item per Jira action: search open issue by label → comment (repeat) or create (new).
// More than massFailureThreshold real failures → one mass issue instead of one bug per test.
// Unexpected passes (test.fail() that passed) always get their own Task.
const cfg = $('Config').first().json;
const p = $('Webhook').first().json.body;
const project = cfg.jiraProject;
const threshold = Number(cfg.massFailureThreshold);

// Jira Cloud REST v3 wants Atlassian Document Format for descriptions and comments
const text = (part) =>
  typeof part === 'string'
    ? { type: 'text', text: part }
    : { type: 'text', text: part.text, marks: [{ type: 'link', attrs: { href: part.href } }] };
const para = (...parts) => ({ type: 'paragraph', content: parts.filter(Boolean).map(text) });
const doc = (...paragraphs) => ({ type: 'doc', version: 1, content: paragraphs });

const buildLink = p.buildUrl ? { text: `build #${p.build}`, href: p.buildUrl } : `build #${p.build}`;
const jql = (issueType, labels) =>
  [`project = "${project}"`, `issuetype = "${issueType}"`, ...labels.map((l) => `labels = "${l}"`), 'statusCategory != Done'].join(' AND ');
const summary = (s) => (s.length > 250 ? `${s.slice(0, 249)}…` : s);
const testParas = (t) => [para(`Test: ${t.title}`), para(`Location: ${t.location} (project ${t.project})`), para(`Error: ${t.error || '(none)'}`)];

const item = (type, issueType, title, tests, labels, searchLabels, description, comment) => ({
  type,
  title,
  tests,
  jql: jql(issueType, searchLabels),
  create: { fields: { project: { key: project }, issuetype: { name: issueType }, summary: summary(title), description, labels } },
  comment: { body: comment },
});

const failures = p.failures.filter((t) => t.kind === 'failure');
const unexpectedPasses = p.failures.filter((t) => t.kind === 'unexpected-pass');
const items = [];

for (const t of unexpectedPasses) {
  items.push(
    item(
      'task', 'Task', `[Auto] Known bug may be fixed: ${t.title}`, [t],
      ['auto-test', 'nightly', `at-${t.id}`], ['auto-test', `at-${t.id}`],
      doc(
        para('This test is pinned with test.fail() as a known app bug, but it passed in ', buildLink, '.'),
        para(`Test: ${t.title}`),
        para(`Location: ${t.location} (project ${t.project})`),
        para(`Suite: ${p.suite}`),
        para('To do: verify the bug is fixed in the app, then remove test.fail() from the test and mark the bug fixed in docs/bugs-found.md.'),
      ),
      doc(para('Still passing in ', buildLink, '.')),
    ),
  );
}

if (p.counts.failed > threshold) {
  const notListed = p.counts.failed - failures.length;
  const list = [
    ...failures.map((t) => para(`${t.title} (${t.location}): ${t.error || '(no error)'}`)),
    ...(notListed > 0 ? [para(`+ ${notListed} more, see the build.`)] : []),
  ];
  items.push(
    item(
      'mass', 'Bug', `[Auto] Build #${p.build}: ${p.counts.failed} tests failed`, failures,
      ['auto-test', 'auto-test-mass', 'nightly'], ['auto-test-mass'],
      doc(
        para(`${p.counts.failed} tests failed in `, buildLink, ` (suite ${p.suite}).`),
        para(`More than ${threshold} failures: one issue instead of one per test. Likely an environment or shared cause.`),
        ...list,
      ),
      doc(para('Failed again in ', buildLink, `: ${p.counts.failed} tests failed.`), ...list),
    ),
  );
} else {
  for (const t of failures) {
    items.push(
      item(
        'bug', 'Bug', `[Auto] ${t.title}`, [t],
        ['auto-test', 'nightly', `at-${t.id}`], ['auto-test', `at-${t.id}`],
        doc(...testParas(t), para(`Suite: ${p.suite}`), para('First failed in ', buildLink, '.')),
        doc(para('Failed again in ', buildLink, `: ${t.error || '(no error)'}`)),
      ),
    );
  }
}

return items.map((json) => ({ json }));

// One email for the build: mass issue or new/repeat bugs, plus unexpected passes separately.
const cfg = $('Config').first().json;
const p = $('Webhook').first().json.body;
const results = $input.all().map((i) => i.json);

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const issue = (key) => `<a href="${esc(cfg.jiraSiteUrl)}/browse/${esc(key)}">${esc(key)}</a>`;
const build = p.buildUrl ? `<a href="${esc(p.buildUrl)}">#${p.build}</a>` : `#${p.build}`;
const testLine = (t) => `${esc(t.title)} <code>${esc(t.location)}</code>${t.error ? `: ${esc(t.error)}` : ''}`;
const section = (heading, rows) => (rows.length ? `<h3>${heading}</h3><ul>${rows.map((r) => `<li>${r}</li>`).join('')}</ul>` : '');
const c = p.counts;

const html = [
  `<p>${esc(p.job)} build ${build} (suite ${esc(p.suite)}) failed: ${c.failed} failed, ${c.unexpectedPasses} unexpected passes, ` +
    `${c.expectedFailures} expected failures, ${c.flaky} flaky, ${c.passed} passed.</p>`,
];

const mass = results.find((r) => r.type === 'mass');
if (mass) {
  const notListed = c.failed - mass.tests.length;
  html.push(
    `<h3>Mass failure: ${c.failed} tests failed</h3>`,
    `<p>More than ${esc(cfg.massFailureThreshold)} failures, so one issue instead of one per test: ` +
      `${issue(mass.jiraKey)} (${mass.status === 'new' ? 'new' : 'updated'}).</p>`,
    `<ul>${mass.tests.map((t) => `<li>${testLine(t)}</li>`).join('')}${notListed > 0 ? `<li>+ ${notListed} more, see the build</li>` : ''}</ul>`,
  );
} else {
  const bugs = results.filter((r) => r.type === 'bug');
  const row = (r) => `${issue(r.jiraKey)} ${testLine(r.tests[0])}`;
  html.push(
    section('New bugs', bugs.filter((r) => r.status === 'new').map(row)),
    section('Failed again (comment added)', bugs.filter((r) => r.status === 'repeat').map(row)),
  );
}

const tasks = results.filter((r) => r.type === 'task');
html.push(
  section(
    'Known bugs that may be fixed (unexpected passes)',
    tasks.map((r) => `${issue(r.jiraKey)} ${r.status === 'new' ? '(new task)' : '(still passing)'} ${testLine(r.tests[0])}`),
  ),
);
if (p.moreFailures > 0 && !mass) html.push(`<p>+ ${p.moreFailures} more failed tests, see the build.</p>`);

const subject =
  `[${p.job}] Build #${p.build} failed: ${c.failed} failed` + (c.unexpectedPasses ? `, ${c.unexpectedPasses} unexpected passes` : '');
return [{ json: { subject, html: html.filter(Boolean).join('\n') } }];

// Existing tracker rows (none on the first run: the read/extract errors are skipped) + one row per failed test.
const p = $('Webhook').first().json.body;
const old = $input.all().map((i) => i.json).filter((r) => r.Date !== undefined && r.error === undefined);
const date = $now.toFormat('yyyy-LL-dd HH:mm');
const rows = $('Loop results').all().flatMap(({ json: r }) =>
  r.tests.map((t) => ({
    Date: date,
    Job: p.job,
    Build: p.build,
    Suite: p.suite,
    Test: t.title,
    Location: t.location,
    Kind: t.kind,
    'Jira key': r.jiraKey,
    'New/Repeat': r.status === 'new' ? 'New' : 'Repeat',
  })),
);
return [...old, ...rows].map((json) => ({ json }));
